import{_ as e,c as r,o as h,af as i}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"2、【坤】 坤下坤上","description":"橫渠易說 - 2、【坤】 坤下坤上","frontmatter":{"title":"2、【坤】 坤下坤上","description":"橫渠易說 - 2、【坤】 坤下坤上"},"headers":[],"relativePath":"classics/hengqu/004.md","filePath":"classics/hengqu/004.md"}'),l={name:"classics/hengqu/004.md"};function n(t,a,s,d,c,o){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="_2、【坤】-坤下坤上" tabindex="-1">2、【坤】 坤下坤上 <a class="header-anchor" href="#_2、【坤】-坤下坤上" aria-label="Permalink to “2、【坤】 坤下坤上”">​</a></h1><p>以西南為得明，乃安貞之德也；以東北為喪朋，雖得主有慶而不可懷也。西南土之位，東北木之位也。“西南得朋，東北喪朋”，江沱之間，有嫡不以其媵備數，是不能喪朋也；媵遇勞而無怨，卻是能喪朋者，其卒嘯也歌，是“乃終有慶”也。此婦人之教大者也。西南，致養之地，東北，反西南者也，陰陽正合，則陰相對者必陽也。“西南得朋”，是始以類相從而來也。“東北喪朋”，喪朋，相忘之義，聽其自治，不責人，不望人，是喪其朋也，喪朋則有慶矣。江有沱、有汜、有渚，皆是始離而終合之象也。有嫡不以其媵備數，是不能喪朋；媵遇勞而無怨，是能喪朋也，以其能喪朋，故能始離而終合。“之子歸”，自嫡也；“不我以”，“不我與”，“不我過”，皆言其始之不均一也。“其後也悔”，嫡自悔也。處，“既安既處”之處也，始離而終既處也。歌是“乃終有慶”，慶則同有慶。</p><p>彖曰：至哉坤元!萬物資生，乃順承天。坤厚載物，德合無疆。含弘光大，品物咸亨。牝馬地類，行地無疆。柔順利貞，君子攸行。先迷失道，後順得常。</p><p>坤先迷不知所從，故失道；後能順聽，則得其常矣。西南得朋，乃與類行；東北喪朋，乃終有慶。安貞之吉，應地無疆。</p><h3 id="象曰-地勢坤-君子以厚德載物。" tabindex="-1">象曰：地勢坤，君子以厚德載物。 <a class="header-anchor" href="#象曰-地勢坤-君子以厚德載物。" aria-label="Permalink to “象曰：地勢坤，君子以厚德載物。”">​</a></h3><h3 id="初六-履霜堅冰至。-象曰-履霜堅冰-陰始凝也-馴致其道-至堅冰也。" tabindex="-1">初六，履霜堅冰至。 象曰：“履霜堅冰”，陰始凝也，馴致其道，至堅冰也。 <a class="header-anchor" href="#初六-履霜堅冰至。-象曰-履霜堅冰-陰始凝也-馴致其道-至堅冰也。" aria-label="Permalink to “初六，履霜堅冰至。 象曰：“履霜堅冰”，陰始凝也，馴致其道，至堅冰也。”">​</a></h3><h3 id="六二-直方大-不習無不利。-象曰-六二之動-直以方也。-不習無不利-地道光也。" tabindex="-1">六二，直方大，不習無不利。 象曰：六二之動，直以方也。“不習無不利”，地道光也。 <a class="header-anchor" href="#六二-直方大-不習無不利。-象曰-六二之動-直以方也。-不習無不利-地道光也。" aria-label="Permalink to “六二，直方大，不習無不利。 象曰：六二之動，直以方也。“不習無不利”，地道光也。”">​</a></h3><p>地道之有孚者，故曰光也。</p><h3 id="六三-含章可貞-或從王事-無成有終。-象曰-含章可貞-以時發也。-或從王事-知光大也。" tabindex="-1">六三，含章可貞，或從王事，無成有終。 象曰：“含章可貞”，以時發也。“或從王事”，知光大也。 <a class="header-anchor" href="#六三-含章可貞-或從王事-無成有終。-象曰-含章可貞-以時發也。-或從王事-知光大也。" aria-label="Permalink to “六三，含章可貞，或從王事，無成有終。 象曰：“含章可貞”，以時發也。“或從王事”，知光大也。”">​</a></h3><p>六三以陰居陽，不獨有柔順之德，其知光大，含蘊文明，可從王事者也。然不可動以躁妄，故可靜一以俟時；不可有其成功，故無成乃有終也。</p><h3 id="六四-括囊-無咎無譽。-象曰-括囊無咎-慎不害也。" tabindex="-1">六四，括囊，無咎無譽。 象曰：“括囊無咎”，慎不害也。 <a class="header-anchor" href="#六四-括囊-無咎無譽。-象曰-括囊無咎-慎不害也。" aria-label="Permalink to “六四，括囊，無咎無譽。 象曰：“括囊無咎”，慎不害也。”">​</a></h3><h3 id="六五-黃裳元吉。-象曰-黃裳元吉-文在中也。" tabindex="-1">六五，黃裳元吉。 象曰：“黃裳元吉”，文在中也。 <a class="header-anchor" href="#六五-黃裳元吉。-象曰-黃裳元吉-文在中也。" aria-label="Permalink to “六五，黃裳元吉。 象曰：“黃裳元吉”，文在中也。”">​</a></h3><h3 id="上六-龍戰於野-其血玄黃。-象曰-龍戰於野-其道窮也。" tabindex="-1">上六，龍戰於野，其血玄黃。 象曰：“龍戰於野”，其道窮也。 <a class="header-anchor" href="#上六-龍戰於野-其血玄黃。-象曰-龍戰於野-其道窮也。" aria-label="Permalink to “上六，龍戰於野，其血玄黃。 象曰：“龍戰於野”，其道窮也。”">​</a></h3><h3 id="用六-利永貞。-象曰-用六永貞-以大-中-終-也。" tabindex="-1">用六，利永貞。 象曰：“用六永貞”，以大(中)［終］也。 <a class="header-anchor" href="#用六-利永貞。-象曰-用六永貞-以大-中-終-也。" aria-label="Permalink to “用六，利永貞。 象曰：“用六永貞”，以大(中)［終］也。”">​</a></h3><p>文言</p><h3 id="坤至柔而動也剛-至靜而德方-後得主而有常-含萬物而化光。坤道其順乎-承天而時行" tabindex="-1">坤至柔而動也剛，至靜而德方，後得主而有常，含萬物而化光。坤道其順乎，承天而時行! <a class="header-anchor" href="#坤至柔而動也剛-至靜而德方-後得主而有常-含萬物而化光。坤道其順乎-承天而時行" aria-label="Permalink to “坤至柔而動也剛，至靜而德方，後得主而有常，含萬物而化光。坤道其順乎，承天而時行!”">​</a></h3><p>效法故光。 屈伸、動靜、終始各自則，今以剛柔言之，剛何嘗無靜，柔何嘗無動，“坤至柔而動也剛”，則柔亦有剛，靜亦有動，但舉一體，則有屈伸、動靜、終始，乾行不妄，則坤順必時也。</p><h3 id="積善之家-必有餘慶-積不善之家-必有餘殃。" tabindex="-1">積善之家，必有餘慶；積不善之家，必有餘殃。 <a class="header-anchor" href="#積善之家-必有餘慶-積不善之家-必有餘殃。" aria-label="Permalink to “積善之家，必有餘慶；積不善之家，必有餘殃。”">​</a></h3><p>餘慶餘殃，百祥百殃，與中庸必得之義同。善者有後，不善者無後，理當然，其不然者，亦恐遲晚中間。譬之瘠之或秀，腴之或不秀，然而不直之生也幸而免，遇外物大抵適然耳。君子則不恤，惟知有義理。臣弒其君，子弒其父，非一朝一夕之故，其所由來者漸矣，由辯之不早辯也。</p><h3 id="易曰-履霜堅冰至-蓋言順也。直其正也-方其義也-君子敬以直內-義以方外" tabindex="-1">易曰“履霜堅冰至”，蓋言順也。直其正也，方其義也，君子敬以直內，義以方外， <a class="header-anchor" href="#易曰-履霜堅冰至-蓋言順也。直其正也-方其義也-君子敬以直內-義以方外" aria-label="Permalink to “易曰“履霜堅冰至”，蓋言順也。直其正也，方其義也，君子敬以直內，義以方外，”">​</a></h3><p>敬以直內則不失於物，義以方外則得己，敬義一道也。敬所以成仁也，蓋敬則實為之，實為之故成其仁。</p><h3 id="敬義立而德不孤。-直方大-不習無不利-則不疑其所行也。陰雖有美-含之以從王事-弗敢成也-地道也-妻道也-臣道也-地道無成而代有終也。天地變化-草木蕃-天地閉-賢人隱。易曰-括囊無咎無譽-蓋言謹也。君子黃中通理-正位居體-美在其中-而暢於四支-發於事業-美之至也。陰疑於陽必戰-為其嫌於無陽也-故稱龍焉-猶未離其類也-故稱血焉。夫玄黃者-天地之雜也-天玄而地黃。" tabindex="-1">敬義立而德不孤。“直方大，不習無不利”，則不疑其所行也。陰雖有美，含之以從王事，弗敢成也，地道也，妻道也，臣道也，地道無成而代有終也。天地變化，草木蕃；天地閉，賢人隱。易曰“括囊無咎無譽”，蓋言謹也。君子黃中通理，正位居體，美在其中，而暢於四支，發於事業，美之至也。陰疑於陽必戰，為其嫌於無陽也，故稱龍焉；猶未離其類也，故稱血焉。夫玄黃者，天地之雜也，天玄而地黃。 <a class="header-anchor" href="#敬義立而德不孤。-直方大-不習無不利-則不疑其所行也。陰雖有美-含之以從王事-弗敢成也-地道也-妻道也-臣道也-地道無成而代有終也。天地變化-草木蕃-天地閉-賢人隱。易曰-括囊無咎無譽-蓋言謹也。君子黃中通理-正位居體-美在其中-而暢於四支-發於事業-美之至也。陰疑於陽必戰-為其嫌於無陽也-故稱龍焉-猶未離其類也-故稱血焉。夫玄黃者-天地之雜也-天玄而地黃。" aria-label="Permalink to “敬義立而德不孤。“直方大，不習無不利”，則不疑其所行也。陰雖有美，含之以從王事，弗敢成也，地道也，妻道也，臣道也，地道無成而代有終也。天地變化，草木蕃；天地閉，賢人隱。易曰“括囊無咎無譽”，蓋言謹也。君子黃中通理，正位居體，美在其中，而暢於四支，發於事業，美之至也。陰疑於陽必戰，為其嫌於無陽也，故稱龍焉；猶未離其類也，故稱血焉。夫玄黃者，天地之雜也，天玄而地黃。”">​</a></h3><p>正位居體，所以應黃裳之美。</p>',23)])])}const _=e(l,[["render",n]]);export{b as __pageData,_ as default};
